import pyomo.environ as pyo

DATA = {
    "products": ["Drummondville", "Victoriaville"],
    "resources": ["arabica", "robusta"],
    "profit": {"Drummondville": 5, "Victoriaville": 7},
    "usage": {
        "arabica": {"Drummondville": 600, "Victoriaville": 375},
        "robusta": {"Drummondville": 400, "Victoriaville": 625},
    },
    "availability": {"arabica": 24000, "robusta": 17000},
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    model.bags = pyo.Var(
        model.P,
        within=pyo.NonNegativeIntegers,
        bounds=(0, None),
    )

    def obj_rule(m):
        return sum(d["profit"][p] * m.bags[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def resource_rule(m, r):
        return sum(d["usage"][r][p] * m.bags[p] for p in m.P) <= d["availability"][r]

    model.resource_limit = pyo.Constraint(model.R, rule=resource_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "blends": ["Drummondville", "Victoriaville"],
    "beans": ["arabica", "robusta"],
    # grams of each bean type per bag of each blend
    "usage": {
        ("Drummondville", "arabica"): 600,
        ("Drummondville", "robusta"): 400,
        ("Victoriaville", "arabica"): 375,
        ("Victoriaville", "robusta"): 625,
    },
    # profit per bag of each blend
    "profit": {
        "Drummondville": 5,
        "Victoriaville": 7,
    },
    # available stock (grams) of each bean type
    "stock": {
        "arabica": 24000,
        "robusta": 17000,
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.BLENDS = pyo.Set(initialize=d["blends"])
    model.BEANS = pyo.Set(initialize=d["beans"])

    # Decision: number of bags of each blend (indivisible -> integer)
    model.bags = pyo.Var(
        model.BLENDS,
        within=pyo.NonNegativeIntegers,
        bounds=(0, None),
    )

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(d["profit"][b] * m.bags[b] for b in m.BLENDS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # One stock constraint per bean type
    def stock_rule(m, bean):
        return sum(d["usage"][(b, bean)] * m.bags[b] for b in m.BLENDS) <= d["stock"][bean]

    model.stock_limit = pyo.Constraint(model.BEANS, rule=stock_rule)

    return model


